%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: "/dynamicQuery",
	body: { 
		"query" :{
  "aggregate": "CMP_OFERTA_PRODUCTO",
  "pipeline": [
    {
      "\$match": {
        // Aquí usamos el valor dinámico que viene de tu flujo de Mule
        "num_agrupacion": vars.RequestOrder.requestService.productGroupingNumber default 0
      }
    },
    {
      "\$group": {
        "_id": "\$num_agrupacion",
        "bundle": {
          "\$push": {
            "\$cond": [
              { "\$eq": ["\$tipo_producto", "BUNDLE"] },
              "\$\$ROOT",
              "\$\$REMOVE"
            ]
          }
        },
        "primarios": {
          "\$push": {
            "\$cond": [
              { "\$eq": ["\$tipo_producto", "Primario"] },
              "\$\$ROOT",
              "\$\$REMOVE"
            ]
          }
        },
        "secundarios": {
          "\$push": {
            "\$cond": [
              { "\$in": ["\$tipo_producto", ["SECUNDARIO"]] },
              "\$\$ROOT",
              "\$\$REMOVE"
            ]
          }
        }
      }
    },
    {
      "\$addFields": {
        "bundle": { "\$arrayElemAt": ["\$bundle", 0] }
      }
    },
    {
      "\$addFields": {
        "primarios": {
          "\$map": {
            "input": "\$primarios",
            "as": "prim",
            "in": {
              "\$mergeObjects": [
                "\$\$prim",
                {
                  "secundarios": {
                    "\$filter": {
                      "input": "\$secundarios",
                      "as": "sec",
                      "cond": {
                        "\$eq": [
                          "\$\$sec.id_producto_principal",
                          { "\$toString": "\$\$prim._id" }
                        ]
                      }
                    }
                  }
                }
              ]
            }
          }
        }
      }
    },
    {
      "\$addFields": {
        "primarios": {
          "\$sortArray": {
            "input": "\$primarios",
            "sortBy": { "secuencia": 1 }
          }
        }
      }
    },
    {
      "\$addFields": {
        "bundle": {
          "\$mergeObjects": [
            "\$bundle",
            { "primarios": "\$primarios" }
          ]
        }
      }
    },
    {
      "\$project": {
        "_id": 0,
        "num_agrupacion": "\$_id",
        "bundle": 1
      }
    }
  ],
  "cursor": {}
}
	},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client-secret'),
	"client_id" : p('mongo-db-sapi.security.client-id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{

	},
	uriParameters:{

	}
}

%dw 2.0 output application/json
// Funciones de utilidad para el manejo de fechas fun toDate(dateString) = if (dateString != null) dateString as DateTime else null
fun findObject(nombreLlave) = (vars.resultadoSapi filter ($.llave == nombreLlave))[0].objeto default {}
var objectCustomer = findObject("MDM_CLIENTE")
fun buscarIdDireccionPorGis(direcciones, valorGis) = do { var direccionEncontrada = direcciones filter ((item) -> // Filtramos por tipo (Instalación) y por el GIS correspondiente (upper(item.Tipo_Direccion) == "INSTALACION") and (item.Cobertura.Direccion_GIS == valorGis) ) --- // Retornamos el Id_Direccion del primer resultado encontrado direccionEncontrada[0].Id_Direccion default null }
var fechaActual = { "\$date": (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"} }
fun buscarConsecutivo(lista, idBuscado) = (lista filter ($.idProducto == idBuscado))[0].consecutivo default "No encontrado"
var inputData = vars.RequestOrder default {} var bundleSource = payload.result[0].bundle --- { "Servicio_Tramite": { "_id": { "\$oid": "000000000000000000000000" }, "Fecha_Creacion": fechaActual, "Fecha_Modificacion": null, "Usuario_Modificacion": null, "Usuario_Creacion": inputData.createdBy default null, "Actualizacion_Extractor": null, "Id_Cuenta_Servicio": vars.consecutivosProductos.bundle.consecutivo,
// Aquí inyectamos el bundle completo del origen "Bundle": { "_id": bundleSource."_id", "Fecha_Creacion": bundleSource.fecha_creacion, "Fecha_Modificacion": bundleSource.fecha_modificacion, "Usuario_Modificacion": bundleSource.usuario_modifico, "Usuario_Creacion": bundleSource.usuario_creo, "Actualizacion_Extractor": null, "Codigo_Configuracion": bundleSource.cod_configuracion, "Numero_Agrupacion": bundleSource.num_agrupacion, "Tipo_Producto": bundleSource.tipo_producto, "Tipo_Servicio": bundleSource.tipo_servicio, "Subtipo_Servicio": bundleSource.subtipo_servicio, "Subtipo_Producto": bundleSource.subtipo_producto, "Secuencia": bundleSource.secuencia, "Dependencia": bundleSource.dependencia, "Clasificacion": bundleSource.clasificacion, "Nombre": bundleSource.producto, "Icono": bundleSource.icono, "Id_Clase_Servicio": 0, "Id_Item": null, "Id_Item_Padre": null, "id_opcional_auxiliar": bundleSource.id_opcional_auxiliar, "Id_Servicio": vars.consecutivosProductos.bundle.consecutivo, "Id_Subtipo_Producto": bundleSource.id_subtipo_producto as Number default 0, "Id_Subtipo_Servicio": bundleSource.id_subtipo_servicio as Number default 0, "Id_Tipo_Producto": bundleSource.id_tipo_producto as Number default 0, "Id_Tipo_Servicio": bundleSource.id_tipo_servicio as Number default 0, "Display": bundleSource.display, "Estado": bundleSource.estado, "Cantidad_Minima": bundleSource.cantidad_minima, "Cantidad_Maxima": bundleSource.cantidad_maxima, "Precio_Oferta": bundleSource.precio_oferta map (item) -> { "Canal_Venta": item.canal_venta, "Precio_Sin_Iva": item.precio_sin_iva, "Precio_Con_Iva": item.precio_con_iva, "Iva": item.iva }, "Caracteristicas_Producto_Oferta": bundleSource.caracteristicas_producto_oferta default [], "Agrupa_filtros_oferta": bundleSource.agrupa_filtros_oferta, "Valor_Especificacion_Tecnica_Oferta": bundleSource.valor_espec_tecnica_oferta, "Parametros_bundle": bundleSource.parametros_bundle map (param) -> { "Parametro": param.parametro, "Tipo_Parametro": param.tipo_parametro, "Valor": param.valor }, "Primarios": bundleSource.primarios map (primario) -> { "_id": primario."_id", "Fecha_Creacion": primario.fecha_creacion, "Fecha_Modificacion": primario.fecha_modificacion, "Usuario_Modificacion": primario.usuario_modifico, "Usuario_Creacion": primario.usuario_creo, "Actualizacion_Extractor": primario.actualizacion_extractor, "Codigo_Configuracion": primario.cod_configuracion, "Numero_Agrupacion": primario.num_agrupacion, "Tipo_Producto": primario.tipo_producto, "Tipo_Servicio": primario.tipo_servicio, "Subtipo_Servicio": primario.subtipo_servicio, "Subtipo_Producto": primario.subtipo_producto, "Secuencia": primario.secuencia, "Dependencia": primario.dependencia, "Clasificacion": primario.clasificacion, "Nombre": primario.producto, "Icono": primario.icono, "Display": primario.display, "Estado": primario.estado, "Cantidad_Minima": primario.cantidad_minima, "Cantidad_Maxima": primario.cantidad_maxima, "Precio_Oferta": primario.precio_oferta default [], "Caracteristicas_Producto_Oferta": primario.caracteristicas_producto_oferta default [], "Agrupa_filtros_oferta": primario.agrupa_filtros_oferta, "Valor_Especificacion_Tecnica_Oferta": primario.valor_espec_tecnica_oferta, "Id_Clase_Servicio": primario.serviceclass as Number default null, "Disponibilidad": primario.flag_disponibilidad, "Agendamiento": primario.flag_agendamiento, "Aprovisionamiento": primario.flag_aprovisionamiento, "Facturacion": primario.flag_facturacion, "Accion": null, "Id_Item": null, "Id_Item_Padre": null, "Id_Tipo_Producto": primario.id_tipo_producto as Number default null, "Id_Tipo_Servicio": primario.id_tipo_servicio as Number default null, "Id_Subtipo_Servicio": primario.id_subtipo_servicio as Number default null, "Id_Subtipo_Producto": primario.id_subtipo_producto as Number default 0, "Id_Servicio": buscarConsecutivo(vars.consecutivosProductos.primarios,primario."_id"."\$oid"), "id_opcional_auxiliar": primario.id_opcional_auxiliar, "Atributos": flatten([ (primario.atributos_agendamiento default []) map (attr) -> { "Nombre": attr.Nombre, "Valor": attr.valor, "Tipo": "Agendamiento" }, (primario.atributos_disponibilidad default []) map (attr) -> { "Nombre": attr.Nombre, "Valor": attr.valor, "Tipo": "Disponibilidad" }, (primario.atributos_aprovisionamiento default []) map (attr) -> { "Nombre": attr.Nombre, "Valor": attr.valor, "Tipo": "Aprovisionamiento" } ]), "tipo_adicional": null, "Parametros_Producto": [], "seleccionado": false, "deshabilitado": false, "Descuento": 0, "PrecioFinal": 0, // Aquí podrías anidar el mapeo de Secundarios si fuera necesario "Secundarios": primario.secundarios map (secundario, sIndex) -> { "_id": secundario."_id", "Fecha_Creacion": secundario.fecha_creacion, "Fecha_Modificacion": secundario.fecha_modificacion, "Usuario_Modificacion": secundario.usuario_modifico, "Usuario_Creacion": secundario.usuario_creo, "Actualizacion_Extractor": primario.actualizacion_extractor, "Codigo_Configuracion": secundario.cod_configuracion, "Numero_Agrupacion": secundario.num_agrupacion as Number default 0, "Tipo_Producto": secundario.tipo_producto, "Tipo_Servicio": secundario.tipo_servicio, "Subtipo_Servicio": secundario.subtipo_servicio, "Subtipo_Producto": secundario.subtipo_producto, "Secuencia": secundario.secuencia as Number default 0, "Dependencia": secundario.dependencia as Number default 0, "Clasificacion": secundario.clasificacion, "Nombre": secundario.producto, "Icono": secundario.icono, "Display": secundario.display, "Estado": secundario.estado, "Cantidad_Minima": secundario.cantidad_minima as Number default 0, "Cantidad_Maxima": secundario.cantidad_maxima as Number default 0, "Precio_Oferta": secundario.precio_oferta, "Caracteristicas_Producto_Oferta": secundario.caracteristicas_producto_oferta, "Agrupa_filtros_oferta": secundario.agrupa_filtros_oferta, "Valor_Especificacion_Tecnica_Oferta": secundario.valor_espec_tecnica_oferta, "Id_Clase_Servicio": secundario.serviceclass as Number default 0, "Disponibilidad": secundario.flag_disponibilidad default false, "Agendamiento": secundario.flag_agendamiento default false, "Aprovisionamiento": secundario.flag_aprovisionamiento default false, "Facturacion": secundario.flag_facturacion default false, "Accion": null, "Id_Item": null, "Id_Item_Padre": null , "Id_Tipo_Producto": secundario.id_tipo_producto as Number default 0, "Id_Tipo_Servicio": secundario.id_tipo_servicio as Number default 0, "Id_Subtipo_Servicio": secundario.id_subtipo_servicio as Number default 0, "Id_Subtipo_Producto": secundario.id_subtipo_producto as Number default 0, "Id_Servicio": buscarConsecutivo(vars.consecutivosProductos.secundarios,secundario."_id"."\$oid"), "id_opcional_auxiliar": secundario.id_opcional_auxiliar, "Atributos": flatten([ (secundario.atributos_agendamiento) map (attr) -> { "Nombre": attr.Nombre, "Valor": attr.valor, "Tipo": attr.Tipo_Atributo }, (secundario.atributos_disponibilidad) map (attr) -> { "Nombre": attr.Nombre, "Valor": attr.valor, "Tipo": attr.Tipo_Atributo }, (secundario.atributos_aprovisionamiento) map (attr) -> { "Nombre": attr.Nombre, "Valor": attr.valor, "Tipo": attr.Tipo_Atributo } ]), "tipo_adicional": null, "Parametros_Producto": [], "seleccionado": false, "deshabilitado": false, "Descuento": 0, "PrecioFinal": 0 }, "Adicionales": [], "Gold": "", "Numero": "" } },
"Bundle_Clausula_Permanencia": null, "Opcionales": [], "Promociones": [], "Cliente": null, "Estado": null, "Id_Orden_Tramite": null, "Id_Cuenta_Facturacion": "0", "Sistema_Origen": null, "Id_Direccion_Instalacion": buscarIdDireccionPorGis(objectCustomer.Direcciones,inputData.requestCustomer.adreessGisCode) default 1, "Fecha_Activacion": null, "Clausula_Permanencia": null, "Numero_Conexion_Anterior": { "\$numberLong": "0" }, "Id_SalesForce": 0, "Integration_Id": vars.consecutivosProductos.bundle.consecutivo, "Caracteristica_Servicio": [], "Adjuntos": [], "Proyecto": null, "Riesgo_Churn": null, "Servicios_Auxiliares": [], "Is_Pago_Recurrente": false, "Promociones_Condicionadas": [], "Descuento": 0, "PrecioFinal": 0, "Cambio_Tecnologia_Migrado": false } }

