// Definición de la función fun buscarAccionAdd(listaAcciones) = ( (listaAcciones filter ($.Accion == "ADD"))[0] default {} )
var objectAccion = buscarAccionAdd(vars.claseServicioHijo.Acciones)
--- do { // 1. Tomamos lo que ya tiene la variable o inicializamos con vacío var acumulado = vars.serviciosHijos default []
// 2. Creamos el objeto del consecutivo actual var resultadoActual = { "Accion": objectAccion.Accion, "Agendamiento": payload.Agendamiento, "Aprovisionamiento": payload.Aprovisionamiento, "Disponibilidad": payload.Disponibilidad, "Atributos": payload.Atributos map (item, index) -> { "Nombre": item.Nombre, "Valor": item.Valor, "Tipo": item.Tipo_Atributo, "Clase": item.Clase_Atributo, "Nuevo": true, // Valor fijo "Display": 0 // Valor fijo }, "Clase_Servicio": vars.claseServicioHijo.Nombre, "Codigo_Configuracion": payload.Codigo_Configuracion, "Extendido": vars.claseServicioHijo.Extendida, "Id_Clase_Servicio": payload.Id_Clase_Servicio, "Id_Item": payload.Id_Item, "Id_Servicio": payload.Id_Servicio, "Id_Subtipo_Servicio": payload.Id_Subtipo_Servicio, "Id_Tipo_Servicio": payload.Id_Tipo_Servicio, "Nombre": payload.Nombre, "Nuevo": true, "Puertos": [], "Rollback": [], "Commit": [], "Servicios_Hijos": [] } --- // 3. Retornamos la lista con el nuevo elemento al final acumulado ++ [resultadoActual] }

%dw 2.0
output application/json

// Definición de la función
fun buscarAccionAdd(listaAcciones) = (
    (listaAcciones filter ($.Accion == "ADD"))[0] default {}
)

var objectAccion = buscarAccionAdd(vars.claseServicio.Acciones)


---
do {
    // 1. Tomamos lo que ya tiene la variable o inicializamos con vacío
    var acumulado = vars.serviciosPrimarios default []

    // 2. Creamos el objeto del consecutivo actual
    var resultadoActual = {
		"Accion": objectAccion.Accion,
		"Agendamiento": payload.Agendamiento,
		"Aprovisionamiento": payload.Aprovisionamiento,
		"Disponibilidad": payload.Disponibilidad,
		"Atributos": payload.Atributos map (item, index) -> {
	        "Nombre": item.Nombre,
	        "Valor": item.Valor,
	        "Tipo": item.Tipo_Atributo,
	        "Clase": item.Clase_Atributo,
	        "Nuevo": true, // Valor fijo
	        "Display": 0   // Valor fijo
    	},"Clase_Servicio": vars.claseServicio.Nombre,
		"Codigo_Configuracion": payload.Codigo_Configuracion,
		"Extendido": vars.claseServicio.Extendida,
		"Id_Clase_Servicio": payload.Id_Clase_Servicio,
		"Id_Item": payload.Id_Item,
		"Id_Servicio": payload.Id_Servicio,
		"Id_Subtipo_Servicio": payload.Id_Subtipo_Servicio,
		"Id_Tipo_Servicio": payload.Id_Tipo_Servicio,
		"Nombre": payload.Nombre,
		"Nuevo": true,
		"Puertos": [],
		"Rollback": [],
		"Commit": [],
		"Servicios_Hijos": vars.serviciosHijos default []
}
    ---
    // 3. Retornamos la lista con el nuevo elemento al final
    acumulado ++ [resultadoActual]
}

ee:message.ee:set-payload:
%dw 2.0
output application/json

fun obtenerDireccionPorId(idBuscado) = (
    (vars.clienteTramite.Cliente_Tramite.Direcciones filter ($.Id_Direccion == idBuscado))[0] default null
)

// Definición de la función de homologación
fun homologarTecnologia(tipo: String) = (
    tipo match {
        case "FTTH" -> "FIBRA"
        case "FTTC" -> "FTTC"
        else -> upper(tipo)
    }
    )

var fechaActual = (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}

var direccion = obtenerDireccionPorId(vars.resultadoProductos.Servicio_Tramite.Id_Direccion_Instalacion)

---
{
	basePath: p("oracle-sapi.base-path"),
	host: p("oracle-sapi.host"),
	port: p("oracle-sapi.port"),
	method: "POST",
	path: p("oracle-sapi.m6.path") ++ p("oracle-sapi.m6.inventario.path") ++ p("oracle-sapi.m6.inventario.procesos.path") ++ p("oracle-sapi.m6.inventario.procesos.disponibilidad.path"),
	body: {
		  "peticionConsultaDisponibilidad": {
			"encabezadoMensaje": {
			  "idDisponibilidad": vars.orderNumber,
			  "numeroOrdenAprovisionador": vars.orderNumber,
			  "numeroRevision": "1",
			  "tecnologiaETB": vars.resultadoProductos.Servicio_Tramite.Bundle.Tipo_Servicio,
			  "fechaPeticionOrden": fechaActual
			},
			"detalleMensaje": {
			  "modoConsulta": "NO",
			  "tipoDisponibilidad": "NORMAL",
			  "orderItems": flatten(vars.serviciosPrimarios map (padre, index) -> [
				// 1. Mapeo del objeto Padre
				{
					"idProductoTecnico": padre.Clase_Servicio default "",
					"idServicio": padre.Id_Servicio,
					"idServicioPadre": "",
					"idServicioRaiz": padre.Id_Servicio,
					"accion": padre.Accion default "",
					"usoServicio": "01", // Valor fijo según tu ejemplo
					"idProductoTecnicoPadre": "",
					"idProductoTecnicoRaiz": padre.Clase_Servicio,
					"cuentaServicio": {
						"idCuentaServicio": vars.resultadoProductos.Servicio_Tramite.Id_Cuenta_Servicio,
						"direccionServicio": [
						{
							"codigoUnicoDireccion": direccion.Cobertura.Direccion_GIS,
							"codigoDepartamento": direccion.Codigo_Departamento,
							"codigoMunicipio": direccion.Codigo_Municipio,
							"codigoPais": direccion.Codigo_Pais,
							"direccionNormalizada": direccion.Direccion_Normalizada,
							"latitud": direccion.Cobertura.Latitud as String,
							"longitud": direccion.Cobertura.Longitud as String,
							"tecnologias": [
							{
								"nombreTecnologia": homologarTecnologia(direccion.Cobertura.Tecnologia as String default "FTTH"),
								"prioridadTecnologia": "",
								"zona": direccion.Cobertura.Zona,
								"cobertura": {
								"tipoCobertura": direccion.Cobertura.Tipo_Cobertura,
								"nombreCobertura": direccion.Cobertura.NombreCobertura
								}
							}
							]
						}
						]
					},
					"atributos": padre.Atributos default [] map (attr) -> {
						"atributo": attr.Nombre,
						"valor": attr.Valor,
						"accion": padre.Accion
					} default []
				} 
				// Unimos con el mapeo de sus hijos
				] ++ (padre.Servicios_Hijos filter ($.Id_Clase_Servicio as Number != 2102) map (hijo) -> {
					"idProductoTecnico": hijo.Clase_Servicio default "",
					"idServicio": hijo.Id_Servicio,
					"idServicioPadre": padre.Id_Servicio, // Referencia al ID del padre
					"idServicioRaiz": padre.Id_Servicio,
					"accion": hijo.Accion default "",
					"usoServicio": "01",
					"idProductoTecnicoPadre": padre.Clase_Servicio,
					"idProductoTecnicoRaiz": padre.Clase_Servicio,
					"cuentaServicio": {
						"idCuentaServicio": vars.resultadoProductos.Servicio_Tramite.Id_Cuenta_Servicio,
						"direccionServicio": []
					},
					"atributos": hijo.Atributos default [] map (attrH) -> {
						"atributo": attrH.Nombre,
						"valor": attrH.Valor,
						"accion": hijo.Accion
					} default []
				})
			)
			}
		  }
		},
	headers: {
	"client_secret" : p('oracle-sapi.security.client-secret'),
	"client_id" : p('oracle-sapi.security.client-id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{},
	uriParameters: {}
}

%dw 2.0
output application/json

var resultDisponibilidad = payload.respuestaConsultaDisponibilidad

// Definimos las variables con la lógica integrada
var codigoEstado = if(upper(resultDisponibilidad.detalleMensaje.global.disponibilidad) == "FACTIBLE") p('estado-orden-servicio.disponibilidad-factible.codigo') else p('estado-orden-servicio.disponibilidad-no-factible.codigo')
var descEstado = if(upper(resultDisponibilidad.detalleMensaje.global.disponibilidad) == "FACTIBLE") p('estado-orden-servicio.disponibilidad-factible.descripcion') else p('estado-orden-servicio.disponibilidad-no-factible.descripcion')

var fechaActual = {
    "\$date": (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}
---
{
    "Orden_Servicio": {
        "Estado_Orden": {
            "Codigo": codigoEstado,
            "CodigoExcepcion": 0,
            "Descripcion": descEstado,
            "Fecha": fechaActual,
            "Reintentos": 0
        },
        "Numero_Orden": vars.orderNumber,
        "Servicios": vars.serviciosPrimarios
    },
    "Factibilidad": if(upper(resultDisponibilidad.detalleMensaje.global.disponibilidad) == "FACTIBLE") true else false
}

%dw 2.0
output application/json

var resultDisponibilidad = payload.respuestaConsultaDisponibilidad

// Definimos las variables con la lógica integrada
var codigoEstado =  p('estado-orden-servicio.disponibilidad-no-factible.codigo')
var descEstado = p('estado-orden-servicio.disponibilidad-no-factible.descripcion')

var fechaActual = {
    "\$date": (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
}
---
{
    "Orden_Servicio": {
        "Estado_Orden": {
            "Codigo": codigoEstado,
            "CodigoExcepcion": 0,
            "Descripcion": descEstado,
            "Fecha": fechaActual,
            "Reintentos": 0
        },
        "Numero_Orden": vars.orderNumber,
        "Servicios": vars.serviciosPrimarios
    },
    "Factibilidad": false
}
